products.forEach((p,i)=>Object.assign(p,{category:baseCats[i],stock:24,allergens:['Aucun allergène déclaré dans cet exemple','Aucun allergène déclaré dans cet exemple','Blé (gluten)','Aucun allergène déclaré dans cet exemple','Soja, sésame','Lait'][i],storage:[4,5].includes(i)?'Frais':'Sec',origin:'Provenance à confirmer',ingredients:p.name}));
